import os
import random
from typing import List

# We need to generate bytes that will be fed into fuzzer stubs using FUZZ_PARAM_STR/FILENAME.
# The target functions operate on raw byte buffers (memset/memcpy/memcmp/bit-reverse),
# so any arbitrary binary data is valid. To exercise different behaviors, we produce
# varied sizes and content patterns (zeros, 0xFF, ascending, descending, alternating,
# random, repeating short motifs, prime-length payloads, etc.).
# Output must be <= 4096 bytes.

MAX_LEN = 4096


def _pattern_zero(n: int) -> bytes:
    return bytes([0]) * n


def _pattern_ff(n: int) -> bytes:
    return bytes([0xFF]) * n


def _pattern_ascending(n: int) -> bytes:
    # 0..255 repeating
    return bytes([(i & 0xFF) for i in range(n)])


def _pattern_descending(n: int) -> bytes:
    return bytes([(-i) & 0xFF for i in range(n)])


def _pattern_alternating(n: int, a: int = 0x55, b: int = 0xAA) -> bytes:
    return bytes([a if (i & 1) == 0 else b for i in range(n)])


def _pattern_blocks(n: int, block: bytes) -> bytes:
    if not block:
        block = b"\x00"
    reps = (n + len(block) - 1) // len(block)
    return (block * reps)[:n]


def _pattern_random(n: int, rng: random.Random) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _pattern_bitwalk(n: int) -> bytes:
    # Cycle single-bit set across positions to exercise TIFFReverseBits
    out = bytearray(n)
    for i in range(n):
        out[i] = 1 << (i % 8)
    return bytes(out)


def _choose_lengths(rng: random.Random) -> int:
    # Favor a mix of small, medium, edge-case and larger sizes
    choices = []
    # Edge/special sizes
    choices.extend([0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024, 2047, 2048, 4095, 4096])
    # Some primes and odd sizes
    choices.extend([97, 149, 257, 521, 997, 1543, 2053, 3079])
    # Random sizes
    for _ in range(8):
        choices.append(rng.randint(0, MAX_LEN))
    # Bias to not exceed MAX_LEN
    n = rng.choice(choices)
    if n > MAX_LEN:
        n = MAX_LEN
    return n


def _motifs(rng: random.Random) -> List[bytes]:
    # Common small motifs to repeat
    fonts = [
        b"\x00",
        b"\xFF",
        b"\x55\xAA",
        b"\xAA\x55",
        b"\x00\xFF",
        b"\xFF\x00",
        b"AB",
        b"TIFF",
        b"\x00AB\x00",
        bytes([i for i in range(8)]),
        bytes([255 - i for i in range(8)]),
    ]
    # Random 3- to 16-byte motif
    mlen = rng.randint(3, 16)
    fonts.append(bytes(rng.getrandbits(8) for _ in range(mlen)))
    return fonts


def _build_payload(n: int, rng: random.Random) -> bytes:
    if n == 0:
        return b""
    patterns = []
    patterns.append(_pattern_zero(n))
    patterns.append(_pattern_ff(n))
    patterns.append(_pattern_ascending(n))
    patterns.append(_pattern_descending(n))
    patterns.append(_pattern_alternating(n, 0x55, 0xAA))
    patterns.append(_pattern_alternating(n, 0x00, 0xFF))
    patterns.append(_pattern_bitwalk(n))
    patterns.append(_pattern_random(n, rng))
    for m in _motifs(rng):
        patterns.append(_pattern_blocks(n, m))
    # Mix of concatenated segments to introduce non-uniformity
    if n >= 16:
        segs = []
        remaining = n
        while remaining > 0:
            seg_len = min(remaining, rng.randint(1, max(1, n // 4)))
            choice = rng.randrange(6)
            if choice == 0:
                segs.append(_pattern_random(seg_len, rng))
            elif choice == 1:
                segs.append(_pattern_alternating(seg_len))
            elif choice == 2:
                segs.append(_pattern_blocks(seg_len, rng.choice(_motifs(rng))))
            elif choice == 3:
                segs.append(_pattern_ascending(seg_len))
            elif choice == 4:
                segs.append(_pattern_descending(seg_len))
            else:
                segs.append(_pattern_bitwalk(seg_len))
            remaining -= seg_len
        patterns.append(b"".join(segs))
    return rng.choice(patterns)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    n = _choose_lengths(rng)
    payload = _build_payload(n, rng)
    # Ensure final size constraint
    if len(payload) > MAX_LEN:
        payload = payload[:MAX_LEN]
    return payload
